={{ (function() {
  const b = $json.body || {};
  const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const lines = [];

  lines.push('🔔 <b>' + escapeHtml(b.formulario || 'Novo Lead Comercial') + '</b>');
  lines.push('');

  const name = b.name || b.nome;
  if (name) lines.push('👤 <b>Nome:</b> ' + escapeHtml(name));

  const empresa = b.businessName || b.empresa;
  if (empresa) lines.push('🏢 <b>Empresa:</b> ' + escapeHtml(empresa));

  if (b.email) lines.push('📧 <b>E-mail:</b> ' + escapeHtml(b.email));

  const rawPhone = b.phone || b.whatsapp;
  if (rawPhone) {
    const digits = String(rawPhone).replace(/\D/g, '');
    const cleanPhone = digits.length > 0 ? (digits.length <= 11 ? '55' + digits : digits) : '';
    const waLink = cleanPhone ? '<a href="https://wa.me/' + cleanPhone + '">wa.me/' + cleanPhone + '</a>' : escapeHtml(rawPhone);
    lines.push('📱 <b>WhatsApp:</b> ' + waLink);
  }

  if (b.necessidade) lines.push('🎯 <b>Necessidade:</b> ' + escapeHtml(b.necessidade));

  const segmento = b.segment || b.segmento;
  if (segmento) lines.push('🍕 <b>Segmento:</b> ' + escapeHtml(segmento));

  if (b.city || b.state) {
    const loc = [b.city, b.state].filter(Boolean).join(' - ');
    if (loc) lines.push('📍 <b>Localização:</b> ' + escapeHtml(loc));
  }

  if (b.locations && Number(b.locations) > 1) lines.push('🏪 <b>Unidades:</b> ' + escapeHtml(b.locations));

  if (b.monthlyDeliveryOrders && b.monthlyDeliveryOrders !== 'N/A') lines.push('📦 <b>Pedidos/Mês:</b> ' + escapeHtml(b.monthlyDeliveryOrders));

  if (b.platforms) {
    const platStr = Array.isArray(b.platforms) ? b.platforms.join(', ') : b.platforms;
    if (platStr && platStr !== 'N/A') lines.push('🛵 <b>Plataformas:</b> ' + escapeHtml(platStr));
  }

  if (b.preferredContact && b.preferredContact !== 'whatsapp') lines.push('💬 <b>Contato Preferencial:</b> ' + escapeHtml(b.preferredContact));

  const msg = b.currentPain || b.mensagem;
  if (msg && msg !== 'N/A') lines.push('📝 <b>Mensagem:</b> ' + escapeHtml(msg));

  if (b.origem) lines.push('🌐 <b>Origem:</b> ' + escapeHtml(b.origem));

  if (b.id && b.id !== 'N/A') lines.push('🆔 <b>ID:</b> <code>' + escapeHtml(b.id) + '</code>');

  return lines.join('\n');
})() }}
